function solveSudoku(board) {
  const rows = Array.from({ length: 9 }, () => new Set());
  const cols = Array.from({ length: 9 }, () => new Set());
  const boxes = Array.from({ length: 9 }, () => new Set());
  const empty = [];
  const boxOf = (r, c) => 3 * Math.floor(r / 3) + Math.floor(c / 3);
  for (let r = 0; r < 9; r++) {
    for (let c = 0; c < 9; c++) {
      const d = board[r][c];
      if (d === ".") empty.push([r, c]);
      else { rows[r].add(d); cols[c].add(d); boxes[boxOf(r, c)].add(d); }
    }
  }
  const options = (r, c) => "123456789".split("").filter((d) => !rows[r].has(d) && !cols[c].has(d) && !boxes[boxOf(r, c)].has(d));
  const solve = () => {
    if (empty.length === 0) return true;
    let best = 0;                                             // the empty cell with the fewest options
    for (let k = 1; k < empty.length; k++) {
      if (options(...empty[k]).length < options(...empty[best]).length) best = k;
    }
    const [r, c] = empty[best];
    empty[best] = empty[empty.length - 1];
    empty.pop();
    for (const d of options(r, c)) {
      board[r][c] = d; rows[r].add(d); cols[c].add(d); boxes[boxOf(r, c)].add(d);
      if (solve()) return true;
      board[r][c] = "."; rows[r].delete(d); cols[c].delete(d); boxes[boxOf(r, c)].delete(d);
    }
    empty.push([r, c]);                                       // put the cell back for the caller
    return false;
  };
  solve();
}

def solve_sudoku(board):
    rows = [set() for _ in range(9)]
    cols = [set() for _ in range(9)]
    boxes = [set() for _ in range(9)]
    empty = []
    for r in range(9):
        for c in range(9):
            d = board[r][c]
            if d == ".":
                empty.append((r, c))
            else:
                rows[r].add(d); cols[c].add(d); boxes[r // 3 * 3 + c // 3].add(d)

    def options(r, c):
        return [d for d in "123456789" if d not in rows[r] and d not in cols[c] and d not in boxes[r // 3 * 3 + c // 3]]

    def solve():
        if not empty:
            return True
        best = min(range(len(empty)), key=lambda k: len(options(*empty[k])))   # fewest options first
        r, c = empty.pop(best)
        b = r // 3 * 3 + c // 3
        for d in options(r, c):
            board[r][c] = d; rows[r].add(d); cols[c].add(d); boxes[b].add(d)
            if solve():
                return True
            board[r][c] = "."; rows[r].discard(d); cols[c].discard(d); boxes[b].discard(d)
        empty.insert(best, (r, c))        # put the cell back for the caller
        return False

    solve()

