        if (options(empty.get(k)[0], empty.get(k)[1]) < options(empty.get(best)[0], empty.get(best)[1])) best = k;
    int[] cell = empty.remove(best);
    int r = cell[0], c = cell[1], b = r / 3 * 3 + c / 3;
